import {useContext} from 'react'
import {PageContext} from '../../App'

import {SummaryUsageCard, UsageOverviewListDialog} from '.'
import {getCurrentMonthDateRange} from '../../utils/date'

interface TotalUsageCardProps {
  totalUsage: number
  usageMap: Record<string, number>
  isLoadingTotalUsage: boolean
}

export default function TotalUsageCard({totalUsage, usageMap, isLoadingTotalUsage}: TotalUsageCardProps) {
  const {isEnterpriseRoute} = useContext(PageContext)
  const headerAction = isEnterpriseRoute ? (
    <UsageOverviewListDialog totalUsage={totalUsage} usageMap={usageMap} />
  ) : undefined

  return (
    <SummaryUsageCard
      headerAction={headerAction}
      heading="Current metered usage"
      description={`Gross metered usage for ${getCurrentMonthDateRange()}.`}
      monetaryValue={totalUsage}
      testId="total-usage"
      isLoading={isLoadingTotalUsage}
    />
  )
}

try{ TotalUsageCard.displayName ||= 'TotalUsageCard' } catch {}