import {DownloadIcon} from '@primer/octicons-react'
import {Button, Spinner} from '@primer/react'
import {Banner, Dialog} from '@primer/react/experimental'
import React, {createContext, Suspense, useContext, useEffect, useMemo, useRef, useState} from 'react'
import {useQueryLoader} from 'react-relay'

import {doRequest, HTTPMethod} from '../../hooks/use-request'
import useRoute from '../../hooks/use-route'
import {COPILOT_PREMIUM_USAGE_REPORT_ROUTE} from '../../routes'
import {OrganizationPickerRecentQuery, OrganizationPicker} from '../pickers/OrganizationPicker'
import type {OrganizationPickerRecentQuery as OrganizationPickerQueryType} from '../pickers/__generated__/OrganizationPickerRecentQuery.graphql'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {PageContext} from '../../App'

import styles from './PremiumRequestsUsageReportDialog.module.css'

interface Props {
  currentUserEmail?: string
  disableUsageReports?: boolean
  codingAgentEnabled: boolean
  sparkEnabled: boolean
  slug: string
  canRequestAllUsage?: boolean
}

type PremiumRequestsNotification = {
  id: string
  type: 'success' | 'error' | 'info'
  title?: string
  message: string
}

type PremiumRequestsContextPayload = {
  addNotification: (notification: PremiumRequestsNotification) => void
  notifications: PremiumRequestsNotification[]
}

const PremiumRequestsContext = createContext<PremiumRequestsContextPayload>({
  addNotification: () => {}, // noop
  notifications: [],
})

function Root(props: {children: React.ReactNode}) {
  const [notifications, setNotifications] = useState<PremiumRequestsNotification[]>([])

  const addNotification = (notification: PremiumRequestsNotification) => {
    setNotifications(prev => [...prev, notification])
  }

  const ctx = useMemo(() => ({addNotification, notifications}), [notifications])

  return <PremiumRequestsContext.Provider value={ctx}>{props.children}</PremiumRequestsContext.Provider>
}

function PremiumRequestsBanner({message, title, type}: PremiumRequestsNotification) {
  const [isVisible, setIsVisible] = useState(true)

  if (!isVisible) {
    return null
  }

  return (
    <Banner
      variant={type === 'error' ? 'critical' : type}
      hideTitle
      title={title ?? message}
      onDismiss={() => setIsVisible(false)}
      className="mb-3"
    >
      {message}
    </Banner>
  )
}

function PremiumRequestsNotifications() {
  const {notifications} = useContext(PremiumRequestsContext)

  if (notifications.length === 0) {
    return null
  }

  const last = notifications.at(-1)

  if (last === undefined) {
    return null
  }

  // We use `key` to force a remount and reset internal state (e.g., dismissal)
  // when a new notification arrives (even if content is identical).
  return <PremiumRequestsBanner key={last.id} {...last} />
}

function PremiumRequestsTrigger({
  currentUserEmail,
  disableUsageReports = false,
  codingAgentEnabled: _codingAgentEnabled,
  sparkEnabled: _sparkEnabled,
  slug,
  canRequestAllUsage = false,
}: Props) {
  const isStafftoolsRoute = useContext(PageContext).isStafftoolsRoute
  const {path: requestCopilotPremiumUsageReportRoute} = useRoute(COPILOT_PREMIUM_USAGE_REPORT_ROUTE)
  const [isPremiumRequestsDialogOpen, setIsPremiumRequestsDialogOpen] = useState(false)
  const returnFocusRef = useRef(null)
  const {addNotification} = useContext(PremiumRequestsContext)
  const [copilotPremiumRequestOrg, setCopilotPremiumRequestOrg] = useState<string[]>([])
  const copilotPremiumUsageReportDialogEnabled = isFeatureEnabled('billingplatform_copilot_premium_usage_report_dialog')
  const [organizationsRef, loadOrganizations] =
    useQueryLoader<OrganizationPickerQueryType>(OrganizationPickerRecentQuery)

  const handleNotification = (notification: Omit<PremiumRequestsNotification, 'id'>) => {
    addNotification({...notification, id: crypto.randomUUID()})
  }

  const handleCopilotPremiumReportDialogSubmit = async (e: React.FormEvent<EventTarget>) => {
    e.preventDefault()
    const requestData = {
      organization: copilotPremiumRequestOrg[0],
    }

    try {
      const res = await doRequest(HTTPMethod.POST, requestCopilotPremiumUsageReportRoute, requestData)

      if (!res.ok) {
        handleNotification({
          type: 'error',
          message: res.data?.error ?? 'There was an issue handling your usage report request',
        })

        return
      }

      handleNotification({
        type: 'success',
        message: `We're preparing your usage report. It may take ~30 minutes to see usage in your report. We'll send an email to ${currentUserEmail} when it's ready.`,
        title: "We're preparing your usage report",
      })
    } catch {
      handleNotification({
        type: 'error',
        message: 'There was an issue handling your usage report request',
      })
    } finally {
      setIsPremiumRequestsDialogOpen(false)
    }
  }

  const handleCopilotPremiumReportRequest = async () => {
    try {
      const res = await doRequest(HTTPMethod.POST, requestCopilotPremiumUsageReportRoute)

      if (!res.ok) {
        handleNotification({
          type: 'error',
          message: res.data?.error ?? 'There was an issue handling your usage report request',
        })

        return
      }

      handleNotification({
        type: 'success',
        message: `We're preparing your usage report. It may take ~30 minutes to see usage in your report. We'll send an email to ${currentUserEmail} when it's ready.`,
        title: "We're preparing your usage report",
      })
    } catch {
      handleNotification({
        type: 'error',
        message: 'There was an issue handling your usage report request',
      })
    }
  }

  const copilotPremiumUsageReportRequestHandler = () => {
    if (copilotPremiumUsageReportDialogEnabled) {
      if (canRequestAllUsage || isStafftoolsRoute) {
        return handleCopilotPremiumReportRequest
      } else {
        return () => setIsPremiumRequestsDialogOpen(true)
      }
    } else {
      return handleCopilotPremiumReportRequest
    }
  }

  // Load organizations when component mounts or slug changes
  useEffect(() => {
    loadOrganizations({slug}, {fetchPolicy: 'store-or-network'})
  }, [slug, loadOrganizations])

  return (
    <div data-testid="premium-request-dialog-container">
      <Button
        leadingVisual={<DownloadIcon />}
        onClick={copilotPremiumUsageReportRequestHandler()}
        disabled={disableUsageReports}
        className={styles.Button}
      >
        Get usage report
      </Button>
      {isPremiumRequestsDialogOpen && (
        <Dialog
          onClose={() => setIsPremiumRequestsDialogOpen(false)}
          title="Premium requests usage report"
          subtitle={`The Copilot premium requests usage report will be emailed when it's ready to ${currentUserEmail}.`}
          returnFocusRef={returnFocusRef}
          aria-labelledby="header"
        >
          <form>
            <div>
              <span id="radio-header">Select organization:</span>
              <Suspense fallback={<Spinner size="small" />}>
                {organizationsRef && (
                  <OrganizationPicker
                    initialSelectedItemIds={[]}
                    preloadedOrganizationsRef={organizationsRef}
                    selectionVariant="single"
                    entityType="report"
                    setSelectedItems={setCopilotPremiumRequestOrg}
                    slug={slug}
                  />
                )}
              </Suspense>
            </div>
            <hr />
            <span>A detailed report will be generated of your metered usage, with all times reported in UTC.</span>
            <div className={styles.Box}>
              <Button onClick={() => setIsPremiumRequestsDialogOpen(false)} className={styles.Button_1}>
                Cancel
              </Button>
              <Button
                type="submit"
                variant="primary"
                onClick={handleCopilotPremiumReportDialogSubmit}
                disabled={disableUsageReports}
              >
                Email me the report
              </Button>
            </div>
          </form>
        </Dialog>
      )}
    </div>
  )
}

export default Object.assign(Root, {
  Trigger: PremiumRequestsTrigger,
  Notifications: PremiumRequestsNotifications,
})

try{ PremiumRequestsContext.displayName ||= 'PremiumRequestsContext' } catch {}
try{ Root.displayName ||= 'Root' } catch {}
try{ PremiumRequestsBanner.displayName ||= 'PremiumRequestsBanner' } catch {}
try{ PremiumRequestsNotifications.displayName ||= 'PremiumRequestsNotifications' } catch {}
try{ PremiumRequestsTrigger.displayName ||= 'PremiumRequestsTrigger' } catch {}