import {Stack, TextInput, FormControl, Textarea} from '@primer/react'
import {Heading, Box} from '@primer/styled-react'
import styles from './CostCenterDetails.module.css'
import {Fonts, Spacing} from '../../utils/style'

interface Props {
  name: string
  setCostCenterName: (name: string) => void
  description?: string
  setCostCenterDescription?: (description: string) => void
  billingAddCostCenterDescription: boolean
}

export function CostCenterDetails({
  name,
  setCostCenterName,
  description = '',
  setCostCenterDescription,
  billingAddCostCenterDescription = false,
}: Props) {
  const isDescriptionTooLong = description.length >= 255

  return billingAddCostCenterDescription ? (
    <>
      <Stack className={styles.fieldSection}>
        <Stack className={styles.fieldHeader}>
          <Heading as="h3" className={`h2-override-shared-component ${styles.sectionHeading}`}>
            Cost center name
          </Heading>
          <span className={styles.fieldDescription}>Provide a unique identifier for the cost center.</span>
        </Stack>

        <FormControl required>
          <FormControl.Label visuallyHidden>Cost Center Name Input</FormControl.Label>
          <TextInput
            block
            type="text"
            data-testid="cost-center-name-input"
            placeholder=""
            value={name}
            maxLength={256}
            onChange={e => setCostCenterName(e.target.value)}
          />
        </FormControl>
      </Stack>

      <Stack className={styles.fieldSection}>
        <Stack className={styles.fieldHeader}>
          <Heading as="h3" className={`h2-override-shared-component ${styles.sectionHeading}`}>
            Description
          </Heading>
        </Stack>

        <FormControl>
          <FormControl.Label visuallyHidden>Cost Center Description Input</FormControl.Label>
          <Textarea
            block
            data-testid="cost-center-description-input"
            placeholder="Describe this cost center in a few words."
            value={description}
            maxLength={256}
            onChange={e => setCostCenterDescription?.(e.target.value)}
            rows={3}
            resize="vertical"
            validationStatus={isDescriptionTooLong ? 'error' : undefined}
          />
          {isDescriptionTooLong && (
            <FormControl.Validation variant="error">
              Description cannot be longer than 255 characters
            </FormControl.Validation>
          )}
        </FormControl>
      </Stack>
    </>
  ) : (
    <Box sx={{mb: Spacing.CardMargin}}>
      <Box sx={{mb: 2}}>
        <Heading as="h3" className="h2-override-shared-component" sx={{fontSize: Fonts.SectionHeadingFontSize}}>
          Cost center name
        </Heading>
        <span>Provide a unique identifier for the cost center.</span>
      </Box>

      <FormControl required>
        <FormControl.Label visuallyHidden>Cost Center Name Input</FormControl.Label>
        <TextInput
          block
          type="text"
          data-testid="cost-center-name-input"
          placeholder=""
          value={name}
          maxLength={256}
          onChange={e => setCostCenterName(e.target.value)}
        />
      </FormControl>
    </Box>
  )
}

try{ CostCenterDetails.displayName ||= 'CostCenterDetails' } catch {}