import {useState} from 'react'
import {Link} from '@primer/react'
import {Banner} from '@primer/react/experimental'

type CostCenterNotificationProps = {
  text: string
  variant: 'critical' | 'warning'
  dismissible?: boolean
  dismissLink?: string
  title?: string
  primaryAction?: {
    label: string
    onClick: () => void
    testId?: string
  }
  link?: {
    href: string
    label?: string
    target?: string
    rel?: string
  }
  'data-testid'?: string
}

function CostCenterNotification({
  text,
  variant,
  dismissible = false,
  title = 'Cost center alert',
  primaryAction,
  link,
  'data-testid': dataTestId = 'cost-center-flash',
}: CostCenterNotificationProps) {
  const [visible, setVisible] = useState(true)

  if (!visible) return null

  const handleDismiss = async () => {
    setVisible(false)
  }

  const description = link ? (
    <>
      {text}{' '}
      <Link
        href={link.href}
        inline
        target={link.target ?? '_blank'}
        rel={
          (link.target ?? '_blank') === '_blank'
            ? [link.rel, 'noopener', 'noreferrer'].filter(Boolean).join(' ')
            : link.rel
        }
      >
        {link.label ?? 'Learn more'}
      </Link>
    </>
  ) : (
    text
  )

  return (
    <Banner
      title={title}
      hideTitle
      description={description}
      variant={variant}
      {...(primaryAction && {
        primaryAction: (
          <Banner.PrimaryAction onClick={primaryAction.onClick} data-testid={primaryAction.testId ?? 'primary-action'}>
            {primaryAction.label}
          </Banner.PrimaryAction>
        ),
      })}
      {...(dismissible && {onDismiss: handleDismiss})}
      data-testid={dataTestId}
    />
  )
}

export default CostCenterNotification

try{ CostCenterNotification.displayName ||= 'CostCenterNotification' } catch {}