interface LicenseDisplayProps {
  licensesCount: number
  budgetDollarAmount: number
  price: number
  showBudgetAmount: boolean
}

export function LicenseDisplay({licensesCount, budgetDollarAmount, price, showBudgetAmount}: LicenseDisplayProps) {
  if (showBudgetAmount) {
    return (
      <span>
        ~ <b>${budgetDollarAmount.toLocaleString()}</b> budget amount
      </span>
    )
  }

  return (
    <span>
      <b>~ {licensesCount.toLocaleString()} licenses</b>{' '}
      <span className="color-fg-muted">at ${price}/license per month</span>
    </span>
  )
}

try{ LicenseDisplay.displayName ||= 'LicenseDisplay' } catch {}