const ValidationErrorBanner = ({
  message,
  bannerRef,
}: {
  message: React.ReactElement
  bannerRef?: React.RefObject<HTMLDivElement>
}) => (
  <Box sx={{mb: 3}} data-testid="error-validation-banner">
    <Banner
      ref={bannerRef}
      hideTitle
      variant="critical"
      title="Custom date range input is empty"
      aria-label="Error: Custom date range input is empty"
    >
      <Banner.Description>{message}</Banner.Description>
    </Banner>
  </Box>
)

type UsageReportNotification = {
  id: string
  type: 'success' | 'error' | 'info' | 'warning'
  title?: string
  message: string
}

type UsageReportContextPayload = {
  addNotification: (notification: UsageReportNotification) => void
  notifications: UsageReportNotification[]
}

const UsageReportContext = createContext<UsageReportContextPayload>({
  addNotification: () => {}, // noop
  notifications: [],
})

function Root(props: {children: React.ReactNode}) {
  const [notifications, setNotifications] = useState<UsageReportNotification[]>([])

  const addNotification = (notification: UsageReportNotification) => {
    setNotifications(prev => [...prev, notification])
  }

  const ctx = useMemo(() => ({addNotification, notifications}), [notifications])

  return <UsageReportContext.Provider value={ctx}>{props.children}</UsageReportContext.Provider>
}

function UsageReportBanner({message, title, type}: UsageReportNotification) {
  const [isVisible, setIsVisible] = useState(true)

  if (!isVisible) {
    return null
  }

  return (
    <Banner
      variant={type === 'error' ? 'critical' : type}
      hideTitle
      title={title ?? message}
      onDismiss={() => setIsVisible(false)}
      className="mb-3"
    >
      <Banner.Description>{message}</Banner.Description>
    </Banner>
  )
}

function UsageReportNotifications() {
  const {notifications} = useContext(UsageReportContext)

  if (notifications.length === 0) {
    return null
  }

  const last = notifications.at(-1)

  if (last === undefined) {
    return null
  }

  // We use `key` to force a remount and reset internal state (e.g., dismissal)
  // when a new notification arrives (even if content is identical).
  return <UsageReportBanner key={last.id} {...last} />
}

interface ReportTypeSelectorProps {
  reportTypeSelections: ReportTypeSelection[]
  usageReportType: number
  onReportTypeChange: (selectedValue: string | null) => void
}

function ReportTypeSelector({reportTypeSelections, usageReportType, onReportTypeChange}: ReportTypeSelectorProps) {
  return (
    <div>
      <span id="report-type-header">Select report type:</span>
      <div className={styles.reportTypeContainer}>
        <RadioGroup name="reportTypeGroup" onChange={onReportTypeChange} aria-labelledby="report-type-header">
          {reportTypeSelections.map((selection: ReportTypeSelection) => (
            <FormControl key={selection.type}>
              <Radio
                value={`${selection.type}`}
                checked={selection.type === usageReportType}
                data-testid={`report-type-radio-${selection.type}`}
              />
              <FormControl.Label className={styles.reportTypeLabel}>
                {selection.displayText}
                <span className={styles.reportTypeDateText}>{selection.dateText}</span>
              </FormControl.Label>
            </FormControl>
          ))}
        </RadioGroup>
      </div>
    </div>
  )
}

interface TimeFrameSelectorProps {
  usageReportType: number
  usageReportPeriod: number
  usageReportPeriodSelections: UsageReportSelection[]
  range: RangeSelection | null
  showEmptyCustomDateRangeError: boolean
  minCustomDateUTC: Date
  onUsageReportPeriodChange: (period: number) => void
  onRangeChange: (selection: RangeSelection | null) => void
  onEmptyCustomDateRangeErrorChange: (show: boolean) => void
}

function TimeFrameSelector({
  usageReportType,
  usageReportPeriod,
  usageReportPeriodSelections,
  range,
  showEmptyCustomDateRangeError,
  minCustomDateUTC,
  onUsageReportPeriodChange,
  onRangeChange,
  onEmptyCustomDateRangeErrorChange,
}: TimeFrameSelectorProps) {
  const datePickerFormat = useResponsiveValue({regular: 'long', narrow: 'short'}, 'long') as string

  const renderSelectedPeriodDisplay = () => {
    const selectedTimeFrame = usageReportPeriodSelections?.find(s => s.type === usageReportPeriod)
    return (
      <>
        {selectedTimeFrame?.displayText}
        <span className={styles.reportTypeDateText}>{selectedTimeFrame?.dateText}</span>
      </>
    )
  }

  const renderCustomDatePickerAnchor = useCallback(
    (anchorProps: React.HTMLAttributes<HTMLElement>) => {
      const hasSelectedRange = range?.from && range?.to
      return (
        <Button
          {...anchorProps}
          trailingVisual={undefined}
          className={hasSelectedRange ? styles.customDatePickerAnchorSelected : styles.customDatePickerAnchor}
        >
          {anchorProps.children}
        </Button>
      )
    },
    [range?.from, range?.to],
  )

  return (
    <>
      <span id="time-frame-header" />
      <div className={styles.timeFrameContainer}>
        <FormControl>
          <FormControl.Label>Select time frame</FormControl.Label>
          {usageReportPeriod === USAGE_REPORT_CUSTOM_RANGE ? (
            <div className={styles.timeFrameFlexContainer}>
              <div className={styles.timeFrameActionMenuContainer}>
                <ActionMenu>
                  <ActionMenu.Button
                    alignContent="start"
                    block
                    className={styles.timeFrameActionMenuButton}
                    aria-label="Time frame selection"
                  >
                    {renderSelectedPeriodDisplay()}
                  </ActionMenu.Button>
                  <ActionMenu.Overlay width="medium" align="start" className={styles.actionMenuOverlayScrollable}>
                    <ActionList selectionVariant="single" showDividers>
                      {usageReportPeriodSelections.map(selection => (
                        <ActionList.Item
                          key={selection.type}
                          selected={selection.type === usageReportPeriod}
                          onSelect={() => onUsageReportPeriodChange(selection.type)}
                        >
                          {selection.displayText}
                          <ActionList.Description>{selection.dateText}</ActionList.Description>
                        </ActionList.Item>
                      ))}
                    </ActionList>
                  </ActionMenu.Overlay>
                </ActionMenu>
              </div>
              <div className={styles.timeFrameDatePickerContainerFullWidth}>
                <DatePicker
                  variant="range"
                  showTodayButton
                  dateFormat={datePickerFormat}
                  placeholder="Choose date..."
                  maxDate={TODAY}
                  maxRangeSize={
                    usageReportType === USAGE_REPORT_SUMMARIZED_TYPE
                      ? MAX_SUMMARIZED_REPORT_CUSTOM_RANGE_DAYS
                      : MAX_DETAILED_REPORT_CUSTOM_RANGE_DAYS
                  }
                  value={range}
                  onChange={selection => {
                    if (!selection) return
                    onRangeChange(selection)
                    onEmptyCustomDateRangeErrorChange(false)
                  }}
                  confirmation
                  minDate={minCustomDateUTC}
                  anchoredOverlayProps={{side: 'outside-bottom'}}
                  anchor={renderCustomDatePickerAnchor}
                />
              </div>
            </div>
          ) : (
            <ActionMenu>
              <ActionMenu.Button
                alignContent="start"
                block
                className={styles.timeFrameActionMenuButton}
                aria-label="Time frame selection"
              >
                {renderSelectedPeriodDisplay()}
              </ActionMenu.Button>
              <ActionMenu.Overlay width="medium" align="start" className={styles.actionMenuOverlayScrollable}>
                <ActionList selectionVariant="single" showDividers>
                  {usageReportPeriodSelections.map(selection => (
                    <ActionList.Item
                      key={selection.type}
                      selected={selection.type === usageReportPeriod}
                      onSelect={() => onUsageReportPeriodChange(selection.type)}
                    >
                      {selection.displayText}
                      <ActionList.Description>{selection.dateText}</ActionList.Description>
                    </ActionList.Item>
                  ))}
                </ActionList>
              </ActionMenu.Overlay>
            </ActionMenu>
          )}
          {/* Error message for custom date range */}
          {usageReportPeriod === USAGE_REPORT_CUSTOM_RANGE && showEmptyCustomDateRangeError && (
            <FormControl.Validation variant="error" className={styles.timeFrameErrorMessage}>
              Specify a custom date range
            </FormControl.Validation>
          )}
        </FormControl>
      </div>
    </>
  )
}

interface FormActionsProps {
  disableUsageReports: boolean
  onCancel: () => void
  onSubmit: (e: React.FormEvent<EventTarget>) => void
}

function FormActions({disableUsageReports, onCancel, onSubmit}: FormActionsProps) {
  return (
    <div className={styles.formActionsContainer}>
      <Link
        href="https://docs.github.com/billing/managing-your-billing/about-usage-reports"
        className={styles.formActionsLearnMoreLink}
        target="_blank"
        rel="noopener noreferrer"
        aria-label="Learn more (opens in new tab)"
      >
        Learn more
      </Link>
      <div className={styles.formActionsButtonGroup}>
        <Button className={`${styles.formActionsCancelButton} ${styles.formActionsSmallButton}`} onClick={onCancel}>
          Cancel
        </Button>
        <Button
          type="submit"
          variant="primary"
          className={styles.formActionsSmallButton}
          onClick={onSubmit}
          disabled={disableUsageReports}
        >
          Email me the report
        </Button>
      </div>
    </div>
  )
}

function getUsagePeriodsByReportType(
  reportTypeSelections: ReportTypeSelection[],
  reportType: number,
): UsageReportSelection[] {
  if (!reportTypeSelections || !Array.isArray(reportTypeSelections)) {
    return []
  }
  return reportTypeSelections.find(rt => rt.type === reportType)?.usagePeriods || []
}

function getInitialUsageReportPeriodSelections(reportTypeSelections: ReportTypeSelection[]): UsageReportSelection[] {
  if (!reportTypeSelections || !Array.isArray(reportTypeSelections)) {
    return []
  }
  return getUsagePeriodsByReportType(reportTypeSelections, USAGE_REPORT_SUMMARIZED_TYPE)
}

function UsageReportTrigger({
  currentUserEmail,
  disableUsageReports = false,
  minCustomDate,
  copilotPremiumReportEnabled = false,
  reportTypeSelections,
  codingAgentEnabled,
  sparkEnabled,
  slug,
  canRequestAllUsage = false,
}: Props) {
  const isStafftoolsRoute = useContext(PageContext).isStafftoolsRoute
  const {path: requestUsageReportRoute} = useRoute(USAGE_REPORT_ROUTE)
  const {path: requestCopilotPremiumUsageReportRoute} = useRoute(COPILOT_PREMIUM_USAGE_REPORT_ROUTE)
  const [usageReportPeriod, setUsageReportPeriod] = useState<number>(USAGE_REPORT_HOURLY_PERIOD)
  const [isDialogOpen, setIsDialogOpen] = useState(false)
  const [isPremiumRequestDialogOpen, setIsPremiumRequestDialogOpen] = useState(false)
  const [range, setRange] = useState<RangeSelection | null>(null)
  const returnFocusRef = useRef(null)
  const bannerRef = useRef<HTMLDivElement>(null)
  const [showEmptyCustomDateRangeError, setEmptyCustomDateRangeError] = useState(false)
  const {addNotification} = useContext(UsageReportContext)
  const [usageReportType, setUsageReportType] = useState<number>(USAGE_REPORT_SUMMARIZED_TYPE)
  const [copilotPremiumRequestOrg, setCopilotPremiumRequestOrg] = useState<string[]>([])
  const copilotPremiumUsageReportDialogEnabled = isFeatureEnabled('billingplatform_copilot_premium_usage_report_dialog')
  const [usageReportPeriodSelections, setUsageReportPeriodSelections] = useState<UsageReportSelection[]>(() =>
    getInitialUsageReportPeriodSelections(reportTypeSelections),
  )
  const [organizationsRef, loadOrganizations] =
    useQueryLoader<OrganizationPickerQueryType>(OrganizationPickerRecentQuery)

  const minCustomDateUTC = useMemo(() => {
    return parseISO(minCustomDate)
  }, [minCustomDate])

  const handleNotification = (notification: Omit<UsageReportNotification, 'id'>) => {
    addNotification({...notification, id: crypto.randomUUID()})
  }

  const handleSubmit = async (e: React.FormEvent<EventTarget>) => {
    e.preventDefault()

    if (usageReportPeriod === USAGE_REPORT_CUSTOM_RANGE && !range) {
      setEmptyCustomDateRangeError(true)
      return
    }

    try {
      const requestData: UsageReportRequest = {
        period: usageReportPeriod,
      }

      requestData.type = usageReportType

      if (usageReportPeriod === USAGE_REPORT_CUSTOM_RANGE && range?.from && range?.to) {
        const {startDate, endDate} = getDateString(range)
        requestData.start = startDate
        requestData.end = endDate
      }

      const {ok, data} = await doRequest<UsageReportRequest>(HTTPMethod.POST, requestUsageReportRoute, requestData)

      if (ok) {
        handleNotification({
          type: 'success',
          message: `We're preparing your usage report. We'll send an email to ${currentUserEmail} when it's ready.`,
        })

        return
      }

      if (data?.code === 'IN_PROGRESS') {
        handleNotification({
          type: 'warning',
          message: `Your request was not processed because you have a pending usage report request. Check ${currentUserEmail} for the report when it's ready.`,
        })

        return
      }

      handleNotification({
        type: 'error',
        message: data?.error ?? 'There was an issue sending your usage report request',
      })
    } catch {
      handleNotification({
        type: 'error',
        message: 'There was an issue sending your usage report request',
      })
    } finally {
      setIsDialogOpen(false)
    }
  }

  const handleReportTypeChange = (selectedValue: string | null) => {
    if (selectedValue) {
      setUsageReportType(Number(selectedValue))
      setUsageReportPeriodSelections(getUsagePeriodsByReportType(reportTypeSelections, Number(selectedValue)))
      setUsageReportPeriod(USAGE_REPORT_HOURLY_PERIOD)
      if (range && Number(selectedValue) !== USAGE_REPORT_LEGACY_TYPE) {
        setRange(null)
        setEmptyCustomDateRangeError(false)
      }

      if (!range) {
        setEmptyCustomDateRangeError(false)
      }
    }
  }

  const handleCopilotPremiumReportDialogSubmit = async (e: React.FormEvent<EventTarget>) => {
    e.preventDefault()
    const requestData = {
      organization: copilotPremiumRequestOrg[0],
    }

    try {
      const res = await doRequest(HTTPMethod.POST, requestCopilotPremiumUsageReportRoute, requestData)

      if (!res.ok) {
        handleNotification({
          type: 'error',
          message: res.data?.error ?? 'There was an issue handling your usage report request',
        })

        return
      }

      handleNotification({
        type: 'success',
        message: `We're preparing your usage report. It may take ~30 minutes to see usage in your report. We'll send an email to ${currentUserEmail} when it's ready.`,
        title: "We're preparing your usage report",
      })
    } catch {
      handleNotification({
        type: 'error',
        message: 'There was an issue handling your usage report request',
      })
    } finally {
      setIsPremiumRequestDialogOpen(false)
    }
  }

  const handleCopilotPremiumReportRequest = async () => {
    try {
      const res = await doRequest(HTTPMethod.POST, requestCopilotPremiumUsageReportRoute)

      if (!res.ok) {
        handleNotification({
          type: 'error',
          message: res.data?.error ?? 'There was an issue handling your usage report request',
        })

        return
      }

      handleNotification({
        type: 'success',
        message: `We're preparing your usage report. It may take ~30 minutes to see usage in your report. We'll send an email to ${currentUserEmail} when it's ready.`,
        title: "We're preparing your usage report",
      })
    } catch {
      handleNotification({
        type: 'error',
        message: 'There was an issue handling your usage report request',
      })
    }
  }

  const copilotPremiumRequestText = () => {
    if (codingAgentEnabled && sparkEnabled) {
      return 'Provides a per-user breakdown of Copilot, Spark, and Copilot coding agent premium requests for the current billing period.'
    } else if (codingAgentEnabled) {
      return 'Provides a per-user breakdown of Copilot and Copilot coding agent premium requests for the current billing period.'
    } else if (sparkEnabled) {
      return 'Provides a per-user breakdown of Copilot and Spark premium requests for the current billing period.'
    }
    return 'Provides a per user breakdown of requests exhausted and their monthly quota for the current billing period.'
  }

  useEffect(() => {
    if (showEmptyCustomDateRangeError) {
      bannerRef.current?.focus()
    }
    loadOrganizations({slug}, {fetchPolicy: 'store-or-network'})
  }, [slug, loadOrganizations, showEmptyCustomDateRangeError])

  const copilotPremiumUsageReportRequestHandler = () => {
    if (copilotPremiumUsageReportDialogEnabled) {
      if (canRequestAllUsage || isStafftoolsRoute) {
        return handleCopilotPremiumReportRequest
      } else {
        return () => setIsPremiumRequestDialogOpen(true)
      }
    } else {
      return handleCopilotPremiumReportRequest
    }
  }

  return (
    <Box onSubmit={handleSubmit} sx={{pt: [2, 0]}} data-testid="usage-report-dialog-container">
      {copilotPremiumReportEnabled ? (
        <ButtonGroup>
          <Button leadingVisual={<DownloadIcon />} onClick={() => setIsDialogOpen(true)}>
            Get usage report
          </Button>

          <ActionMenu>
            <ActionMenu.Button icon={TriangleDownIcon} aria-label="More options" />

            <ActionMenu.Overlay width="medium" className={styles.actionMenuOverlayScrollable}>
              <ActionList showDividers>
                <ActionList.Item onSelect={() => setIsDialogOpen(true)}>
                  Metered billing usage report
                  <ActionList.Description variant="block">
                    Provides a breakdown of all metered usage
                  </ActionList.Description>
                </ActionList.Item>
                <ActionList.Item onSelect={copilotPremiumUsageReportRequestHandler()}>
                  Copilot premium requests usage report
                  <ActionList.Description variant="block">{copilotPremiumRequestText()}</ActionList.Description>
                </ActionList.Item>
              </ActionList>
            </ActionMenu.Overlay>
          </ActionMenu>
        </ButtonGroup>
      ) : (
        <Button leadingVisual={<DownloadIcon />} onClick={() => setIsDialogOpen(true)} sx={{width: ['100%', 'auto']}}>
          Get usage report
        </Button>
      )}

      {isDialogOpen && (
        <Dialog
          onClose={() => setIsDialogOpen(false)}
          title="Get usage report"
          subtitle={`The usage report will be emailed when it's ready to ${currentUserEmail}.`}
          returnFocusRef={returnFocusRef}
          aria-labelledby="header"
          className={styles.dialogContent}
        >
          {disableUsageReports && (
            <Flash
              data-testid="disable-usage-report-banner"
              variant="warning"
              sx={{display: 'flex', alignItems: 'center'}}
            >
              <span>
                Usage reports are temporarily disabled due to planned maintenance. Please try again later or reach out
                to support for assistance.
              </span>
            </Flash>
          )}

          <form>
            {showEmptyCustomDateRangeError && (
              <ValidationErrorBanner
                bannerRef={bannerRef}
                message={
                  <>
                    Please specify a{' '}
                    <Link inline muted href="#">
                      custom date range
                    </Link>{' '}
                    to continue.
                  </>
                }
              />
            )}
            <div className={styles.reportTypeSelectionContainer}>
              <ReportTypeSelector
                reportTypeSelections={reportTypeSelections}
                usageReportType={usageReportType}
                onReportTypeChange={handleReportTypeChange}
              />

              {usageReportType !== USAGE_REPORT_LEGACY_TYPE && (
                <TimeFrameSelector
                  usageReportType={usageReportType}
                  usageReportPeriod={usageReportPeriod}
                  usageReportPeriodSelections={usageReportPeriodSelections}
                  range={range}
                  showEmptyCustomDateRangeError={showEmptyCustomDateRangeError}
                  minCustomDateUTC={minCustomDateUTC}
                  onUsageReportPeriodChange={setUsageReportPeriod}
                  onRangeChange={setRange}
                  onEmptyCustomDateRangeErrorChange={setEmptyCustomDateRangeError}
                />
              )}

              <hr className={styles.fullWidthDivider} />

              <FormActions
                disableUsageReports={disableUsageReports}
                onCancel={() => setIsDialogOpen(false)}
                onSubmit={handleSubmit}
              />
            </div>
          </form>
        </Dialog>
      )}

      {isPremiumRequestDialogOpen && (
        <Dialog
          onClose={() => setIsPremiumRequestDialogOpen(false)}
          title="Premium requests usage report"
          subtitle={`The Copilot premium requests usage report will be emailed when it's ready to ${currentUserEmail}.`}
          returnFocusRef={returnFocusRef}
          aria-labelledby="header"
        >
          <form>
            <div>
              <span id="radio-header">Select organization:</span>
              <Suspense fallback={<Spinner size="small" />}>
                {organizationsRef && (
                  <OrganizationPicker
                    initialSelectedItemIds={[]}
                    preloadedOrganizationsRef={organizationsRef}
                    selectionVariant="single"
                    entityType="report"
                    setSelectedItems={setCopilotPremiumRequestOrg}
                    slug={slug}
                  />
                )}
              </Suspense>
            </div>
            <hr />
            <span>A detailed report will be generated of your metered usage, with all times reported in UTC.</span>
            <Box sx={{pt: 3, display: 'flex', alignItems: 'center', justifyContent: 'flex-end'}}>
              <Button sx={{mr: 2}} onClick={() => setIsPremiumRequestDialogOpen(false)}>
                Cancel
              </Button>
              <Button
                type="submit"
                variant="primary"
                onClick={handleCopilotPremiumReportDialogSubmit}
                disabled={disableUsageReports}
              >
                Email me the report
              </Button>
            </Box>
          </form>
        </Dialog>
      )}
    </Box>
  )
}

export default Object.assign(Root, {
  Trigger: UsageReportTrigger,
  Notifications: UsageReportNotifications,
})

