// eslint-disable-next-line no-restricted-imports
import {useToastContext} from '@github-ui/toast/ToastContext'
import {Button, Select} from '@primer/react'
import {FormControl, Heading, Box, TextInput, Text} from '@primer/styled-react'
import {useState, type ChangeEvent, useEffect} from 'react'

import {HTTPMethod, doRequest} from '../../../hooks/use-request'
import useRoute from '../../../hooks/use-route'
import {CustomerType, DiscountTarget, DiscountType, FundingSource} from '../../../enums'
import {DISCOUNTS_ROUTE} from '../../../routes'
import {pageHeadingStyle} from '../../../utils'

import {DiscountTargetSelector} from './DiscountTargetSelector'

import type {Customer} from '../../../types/common'
import type {CreateDiscountRequest} from '../../../types/customer'
import type {Product} from '../../../types/products'

import {isFeatureEnabled} from '@github-ui/feature-flags'
import styles from './DiscountForm.module.css'

const inputWidth = '18ch'

export interface DiscountFormProps {
  customer: Customer
  enabledProducts: Product[]
  onSuccess?: () => void
  onError?: () => void
}

export function DiscountForm({customer, enabledProducts, onSuccess, onError}: DiscountFormProps) {
  let defaultTarget
  switch (customer.customerType) {
    case CustomerType.Business:
      defaultTarget = DiscountTarget.Enterprise
      break
    case CustomerType.Organization:
      defaultTarget = DiscountTarget.Organization
      break
    case CustomerType.User:
    default:
      defaultTarget = DiscountTarget.Product
  }
  const fixedAmountDiscountsFlag = isFeatureEnabled('billing_fixed_amount_metered_configured_discounts')
  const [discountTarget, setDiscountTarget] = useState<DiscountTarget>(defaultTarget)
  const [discountTargetIds, setDiscountTargetIds] = useState<string[]>([])
  const [startDate, setStartDate] = useState<number>()
  const [endDate, setEndDate] = useState<number>()
  const [discountType, setDiscountType] = useState<DiscountType>(DiscountType.NoDiscountType)
  const [discountAmount, setDiscountAmount] = useState<number>()
  const [fundingSource, setFundingSource] = useState<FundingSource>()

  const [discountTargetValid, setDiscountTargetValid] = useState<boolean>(true)
  const [discountTargetIdsValid, setDiscountTargetIdsValid] = useState<boolean>(true)
  const [startDateValid, setStartDateValid] = useState<boolean>(true)
  const [endDateValid, setEndDateValid] = useState<boolean>(true)
  const [discountTypeValid, setDiscountTypeValid] = useState<boolean>(true)
  const [discountAmountValid, setDiscountAmountValid] = useState<boolean>(true)
  const [fundingSourceValid, setFundingSourceValid] = useState<boolean>(true)

  // Compute today's date in UTC (YYYY-MM-DD) using toISOString()
  const minDate = new Date().toISOString().slice(0, 10)

  // Wrapped so that we can prevent popping when switching targets while the target IDs are invalid
  const wrappedSetDiscountTarget = (newValue: DiscountTarget) => {
    setDiscountTargetIds([])
    setDiscountTargetIdsValid(true)
    setDiscountTarget(newValue)
  }

  const wrappedSetDiscountTargetIds = (newValue: string[]) => {
    setDiscountTargetIds(newValue)
    setDiscountTargetIdsValid(true)
  }

  const onChangeStartDate = (event: ChangeEvent<HTMLInputElement>) => {
    const value = event.target.value
    const newDate = Math.round(new Date(value).getTime() / 1000)
    let valid = true

    if (value && isNaN(newDate)) valid = false
    if (endDate) {
      // End date must come after start date
      if (newDate > endDate) valid = false
      else setEndDateValid(true)
    }

    setStartDateValid(valid)
    // Set the date as long as it is in-fact a date
    if (!isNaN(newDate)) setStartDate(newDate)
  }

  const onChangeEndDate = (event: ChangeEvent<HTMLInputElement>) => {
    const value = event.target.value
    const newDate = Math.round(new Date(value).getTime() / 1000)
    let valid = true

    if (value && isNaN(newDate)) valid = false
    // End date must come after start date
    if (startDate) {
      if (startDate > newDate) valid = false
      else setStartDateValid(true)
    }

    setEndDateValid(valid)
    // Set the date as long as it is in-fact a date
    if (!isNaN(newDate)) setEndDate(newDate)
  }

  const onChangeDiscountType = (event: ChangeEvent<HTMLSelectElement>) => {
    setDiscountTypeValid(true)
    setDiscountType(event.target.value as DiscountType)
  }

  const onChangeFundingSource = (event: ChangeEvent<HTMLSelectElement>) => {
    setFundingSourceValid(true)
    setFundingSource(event.target.value as FundingSource)
  }
  // This effect allows us to validate discount amount after changing discount type
  useEffect(() => {
    validateDiscountAmount(discountAmount?.toString(), {allowBlank: true})
    // eslint-disable-next-line react-hooks/react-compiler
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [discountType])

  const isFixedAmountDiscountType = (type: DiscountType): boolean => {
    return type === DiscountType.FixedAmount || type === DiscountType.RecurringFixedAmount
  }

  const validateDiscountAmountPure = (
    rawValue: string | undefined,
    type: DiscountType,
    opts = {allowBlank: false},
  ): boolean => {
    if (!opts.allowBlank && !rawValue) {
      return false
    }

    if (rawValue) {
      // Check if the string is a valid number format first
      if (!/^\d*\.?\d+$/.test(rawValue.trim())) {
        return false
      }

      // We now know it's safe to parseFloat
      const value = parseFloat(rawValue)

      // For percentage discounts, validate it's an integer between 1-100
      if (type === DiscountType.Percentage) {
        // Check if it's a whole number (no decimal places)
        if (!Number.isInteger(value)) {
          return false
        }
        // Check if it's in the range 1-100
        if (value < 1 || value > 100) {
          return false
        }
      } else {
        // For fixed amount discounts, validate currency format
        const currencyPattern = /^\d+(\.\d{1,2})?$/
        if (!currencyPattern.test(rawValue)) {
          return false
        }
        // Must be greater than 0
        if (isNaN(value) || value <= 0) {
          return false
        }
      }
    }

    return true
  }

  const validateDiscountAmount = (rawValue: string | undefined, opts = {allowBlank: false}): boolean => {
    const isValid = validateDiscountAmountPure(rawValue, discountType, opts)
    setDiscountAmountValid(isValid)
    return isValid
  }
  const onChangeDiscountAmount = (event: ChangeEvent<HTMLInputElement>) => {
    const valid = validateDiscountAmount(event.target.value, {allowBlank: true})
    if (valid) {
      const value = parseFloat(event.target.value)
      setDiscountAmount(value)
    } else {
      // Clear the discount amount when input is invalid
      setDiscountAmount(undefined)
    }
  }

  const validateInputs = () => {
    // State changes are not immediate and therefore we have to separately track whether the inputs are valid
    let valid = true
    if (discountTarget === DiscountTarget.NoDiscountTarget) {
      valid = false
      setDiscountTargetValid(false)
    }
    if (discountTarget !== DiscountTarget.Enterprise && discountTargetIds.length === 0) {
      valid = false
      setDiscountTargetIdsValid(false)
    }
    if (!startDate) {
      valid = false
      setStartDateValid(false)
    }
    if (!endDate) {
      valid = false
      setEndDateValid(false)
    }
    if (discountType === DiscountType.NoDiscountType) {
      valid = false
      setDiscountTypeValid(false)
    } else if (!validateDiscountAmount(discountAmount?.toString())) {
      valid = false
      setDiscountAmountValid(false)
    }
    if (!fundingSource) {
      valid = false
      setFundingSourceValid(false)
    }

    return valid
  }

  // const navigate = useNavigate()
  const {path: createDiscountPath} = useRoute(DISCOUNTS_ROUTE)
  const {addToast} = useToastContext()

  async function createDiscount() {
    const data: CreateDiscountRequest = {
      customerId: customer.customerId,
      endDate: endDate as number,
      percentage: discountType === DiscountType.Percentage ? (discountAmount as number) : 0,
      startDate: startDate as number,
      targets:
        discountTarget === DiscountTarget.Enterprise
          ? [{id: customer.customerId, type: discountTarget}]
          : discountTargetIds.map(id => ({id, type: discountTarget})),
      targetAmount: isFixedAmountDiscountType(discountType) ? (discountAmount as number) : 0,
      discountType,
      ...(fundingSource && {fundingSource}),
    }

    try {
      const {ok} = await doRequest<CreateDiscountRequest>(HTTPMethod.POST, createDiscountPath, data)

      if (!ok) {
        onError?.()
        // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
        addToast({
          type: 'error',
          message: 'There was an issue creating your credit',
          role: 'alert',
        })
      } else {
        onSuccess?.()

        // TODO: Replace with useNavigate once we figure out how to more gracefully handle splitting discounts#index
      }
    } catch {
      onError?.()
      // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
      addToast({
        type: 'error',
        message: 'There was an issue creating your credit',
        role: 'alert',
      })
    }
  }

  const onFormSubmit = async (e: React.FormEvent<EventTarget>) => {
    e.preventDefault()
    const valid = validateInputs()
    if (valid) {
      createDiscount()
    }
  }

  return (
    <>
      <header className="Subhead mt-3">
        <Heading as="h2" className="Subhead-heading" sx={pageHeadingStyle}>
          Apply a new credit
        </Heading>
      </header>
      <Box sx={{maxWidth: '65ch'}}>
        <form onSubmit={onFormSubmit} autoComplete="off">
          <DiscountTargetSelector
            customer={customer}
            discountTarget={discountTarget}
            discountTargetIds={discountTargetIds}
            discountTargetIdsValid={discountTargetIdsValid}
            discountTargetValid={discountTargetValid}
            enabledProducts={enabledProducts}
            setDiscountTarget={wrappedSetDiscountTarget}
            setDiscountTargetIds={wrappedSetDiscountTargetIds}
          />

          <Box sx={{mb: 3}}>
            <Box sx={{mb: 2}}>
              <Heading as="h3" sx={{fontSize: 2}} className="Box-title">
                Date range
              </Heading>
              <span>Specify the date range over which the credit should be applied.</span>
            </Box>
            <div className="Box">
              <div className="Box-row d-flex">
                <FormControl sx={{mr: 2}}>
                  <FormControl.Label>Start date</FormControl.Label>
                  <TextInput type="date" sx={{width: inputWidth}} onChange={onChangeStartDate} min={minDate} />
                  {!startDateValid && (
                    <FormControl.Validation variant="error">Start date is not valid</FormControl.Validation>
                  )}
                </FormControl>
                <FormControl>
                  <FormControl.Label>End date</FormControl.Label>
                  <TextInput type="date" sx={{width: inputWidth}} onChange={onChangeEndDate} min={minDate} />
                  {!endDateValid && (
                    <FormControl.Validation variant="error">End date is not valid</FormControl.Validation>
                  )}
                </FormControl>
              </div>
            </div>
          </Box>

          <Box sx={{mb: 3}}>
            <Box sx={{mb: 2}}>
              <Heading as="h3" sx={{fontSize: 2}} className="Box-title">
                Credit
              </Heading>
              <span>Specify the type of credit and fixed amount or percentage to be applied.</span>
            </Box>
            <div className="Box">
              <div className="Box-row">
                <div className="d-flex">
                  <FormControl sx={{mr: 2}}>
                    <FormControl.Label>Credit type</FormControl.Label>
                    <Select onChange={onChangeDiscountType} className={styles.DiscountForm}>
                      <Select.Option value={DiscountType.NoDiscountType}>Nothing selected</Select.Option>
                      <Select.Option value={DiscountType.RecurringFixedAmount}>Recurring Fixed Amount</Select.Option>
                      <Select.Option value={DiscountType.Percentage}>Percentage</Select.Option>
                      {fixedAmountDiscountsFlag && (
                        <Select.Option value={DiscountType.FixedAmount}>Fixed amount</Select.Option>
                      )}
                    </Select>
                    {!discountTypeValid && (
                      <FormControl.Validation variant="error">Credit type is not valid</FormControl.Validation>
                    )}
                  </FormControl>
                  {discountType !== DiscountType.NoDiscountType && (
                    <FormControl>
                      <FormControl.Label>Credit amount</FormControl.Label>
                      {isFixedAmountDiscountType(discountType) && (
                        <TextInput leadingVisual="$" sx={{width: inputWidth}} onChange={onChangeDiscountAmount} />
                      )}
                      {discountType === DiscountType.Percentage && (
                        <TextInput trailingVisual="%" sx={{width: inputWidth}} onChange={onChangeDiscountAmount} />
                      )}
                      {!discountAmountValid && (
                        <FormControl.Validation variant="error">Credit amount is not valid</FormControl.Validation>
                      )}
                    </FormControl>
                  )}
                </div>
                {isFixedAmountDiscountType(discountType) && (
                  <Text sx={{color: 'fg.muted', fontSize: '12px'}}>
                    Usage will be covered in full up to the specified amount.
                  </Text>
                )}
                {discountType === DiscountType.Percentage && (
                  <Text sx={{color: 'fg.muted', fontSize: '12px'}}>
                    Usage will be discounted by the specified percentage.
                  </Text>
                )}
              </div>
            </div>
          </Box>

          <Box sx={{mb: 3}}>
            <Box sx={{mb: 2}}>
              <Heading as="h3" sx={{fontSize: 2}} className="Box-title">
                Funding Source
              </Heading>
              <span>Specify the funding source for this credit.</span>
            </Box>
            <div className="Box">
              <div className="Box-row">
                <FormControl>
                  <FormControl.Label>Funding source</FormControl.Label>
                  <Select onChange={onChangeFundingSource} className={styles.DiscountForm}>
                    <Select.Option value="">Select funding source</Select.Option>
                    <Select.Option value={FundingSource.BillingCorrection}>Billing correction</Select.Option>
                    <Select.Option value={FundingSource.GitHubForStartups}>GitHub for Startups (GFS)</Select.Option>
                    <Select.Option value={FundingSource.SocialImpact}>Social Impact</Select.Option>
                    <Select.Option value={FundingSource.OpenSource}>Open Source</Select.Option>
                    <Select.Option value={FundingSource.Education}>Education</Select.Option>
                  </Select>
                  {!fundingSourceValid && (
                    <FormControl.Validation variant="error">Funding source is required</FormControl.Validation>
                  )}
                </FormControl>
              </div>
            </div>
          </Box>

          <Button type="submit" variant="primary">
            Create credit
          </Button>
        </form>
      </Box>
    </>
  )
}

try{ DiscountForm.displayName ||= 'DiscountForm' } catch {}