import type {QueryBuilderElement} from '@github-ui/query-builder-element'
import {
  FetchDataEvent,
  FilterItem,
  type FilterProvider,
  type QueryEvent,
} from '@github-ui/query-builder-element/query-builder-api'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {hasMatch} from 'fzy.js'

type ModelData = {
  model: string
  formattedModel: string
}

type ModelsAPIResponse = {
  models: ModelData[]
}

export class BillingModelFilterProvider extends EventTarget implements FilterProvider {
  type = 'filter' as const
  name: string
  slug: string
  priority: number
  singularItemName: string
  value: string

  modelCache: ModelData[] | undefined = undefined

  constructor(
    queryBuilder: QueryBuilderElement,
    {
      name,
      slug,
      value,
      priority,
    }: {
      name: string
      slug: string
      value: string
      priority: number
    },
  ) {
    super()

    this.name = name
    this.slug = slug
    this.singularItemName = name
    this.value = value
    this.priority = priority
    queryBuilder.addEventListener('query', this)
    queryBuilder.attachProvider(this)
  }

  async handleEvent(event: QueryEvent) {
    const lastElement = event.parsedQuery.at(-1)!

    if (
      (lastElement.value !== '' || this.priority <= 5) &&
      lastElement?.type !== 'filter' &&
      !event.parsedQuery.some(e => e.type === 'filter' && e.filter === this.value) &&
      (hasMatch(lastElement?.value, this.name) || hasMatch(lastElement?.value, this.value))
    ) {
      this.dispatchEvent(new Event('show'))
    }

    if (lastElement?.type !== this.type || lastElement.filter !== this.value) return

    if (!this.modelCache) {
      // Immediately set this to avoid multiple requests
      this.modelCache = []
      const fetchPromise = this.fetchModels(event)
      this.dispatchEvent(new FetchDataEvent(fetchPromise))
    } else {
      for (const model of this.modelCache) {
        this.#emitSuggestion(model.model, model.formattedModel, lastElement.value)
      }
    }
  }

  async fetchModels(event: QueryEvent) {
    let modelData: ModelsAPIResponse
    const url = '/billing/copilot_models'
    try {
      const response = await verifiedFetchJSON(url, {method: 'GET'})
      if (response.status !== 200) {
        this.modelCache = undefined
        return
      }

      modelData = await response.json()
      if (!modelData?.models) return

      // Cache the models
      this.modelCache = modelData.models

      // Emit suggestions for filtered models
      const query = event.parsedQuery.at(-1)!.value
      for (const modelResult of modelData.models) {
        this.#emitSuggestion(modelResult.model, modelResult.formattedModel, query)
      }
    } catch {
      this.modelCache = undefined
      return
    }
  }

  #emitSuggestion(name: string, value: string, query: string): void {
    if (query && !hasMatch(query, value)) return

    this.dispatchEvent(
      new FilterItem({
        filter: this.value,
        value,
        name,
      }),
    )
  }
}
