import {Details, Link, ProgressBar, useDetails} from '@primer/react'
import {useMemo} from 'react'
import {Octicon} from '@primer/react/deprecated'
import {ChevronDownIcon, ChevronRightIcon} from '@primer/octicons-react'
import type {UsageTableDataCell, UsageTableData, GroupSelection} from '../../../types/usage'

import sharedStyles from '../UsageTable/UsageTableRow.module.css'
import styles from './PremiumRequestUsageTableRow.module.css'
import PremiumRequestUsageSubTable from './PremiumUsageRequestSubtable'
import {UsageGrouping} from '../../../enums'
import {GitHubAvatar} from '@github-ui/github-avatar'

interface PremiumRequestUsageTableRowProps {
  cells: UsageTableDataCell[]
  groupBy?: GroupSelection
  subtable: UsageTableData | null
  isSubtable: boolean
  showProgressBar: boolean
  premiumRequestsQuota?: string
}

export default function PremiumRequestUsageTableRow({
  cells,
  groupBy,
  subtable,
  isSubtable,
  showProgressBar,
  premiumRequestsQuota,
}: PremiumRequestUsageTableRowProps) {
  const {getDetailsProps, open} = useDetails({closeOnOutsideClick: false})
  const expandable = subtable != null && subtable.rows.length > 0

  const consumedIncludedRequestsValue = cells[1]?.value
  const progressPercentage = useMemo(() => {
    const consumedNumber = Number(consumedIncludedRequestsValue || '0')
    const quotaNumber = Number(premiumRequestsQuota || '0')

    if (isNaN(consumedNumber) || isNaN(quotaNumber)) {
      return 0
    }
    if (quotaNumber === 0) {
      return 100
    }
    return Math.min((consumedNumber / quotaNumber) * 100, 100)
  }, [consumedIncludedRequestsValue, premiumRequestsQuota])

  const progressDisplayValue = useMemo(() => {
    return `${consumedIncludedRequestsValue || '0'}/${premiumRequestsQuota || '0'}`
  }, [consumedIncludedRequestsValue, premiumRequestsQuota])

  const getRowContent = (): React.ReactElement => {
    return (
      <div className={sharedStyles.trStyle}>
        {expandable && (
          // Make the clickable area a bit larger
          <Details {...getDetailsProps()} className={sharedStyles.Details}>
            <summary
              style={{padding: 'var(--base-size-8)'}}
              aria-label={open ? 'Hide Usage Breakdown' : 'Show Usage Breakdown'}
              data-testid={'usage-details'}
            >
              <Octicon icon={open ? ChevronDownIcon : ChevronRightIcon} />
            </summary>
          </Details>
        )}
        {isSubtable ? <div style={{width: 56}} /> : null}

        <div className={styles.identifierCell} data-testid="identifier-td">
          {getFirstColumnContent()}
        </div>

        <div
          className={styles.fixedWidthCell}
          style={isSubtable ? {} : {color: 'var(--fgColor-muted)'}}
          data-testid="included-requests-td"
        >
          {showProgressBar ? (
            <div className={styles.progressBarContainer}>
              <ProgressBar
                aria-label="Included premium requests progress"
                aria-valuetext={`${progressDisplayValue} premium requests used`}
                bg="accent.emphasis"
                progress={progressPercentage}
                barSize="small"
              />

              <span>{progressDisplayValue}</span>
            </div>
          ) : (
            <span>{cells[1]?.value}</span>
          )}
        </div>
        <div
          className={styles.fixedWidthCell}
          style={isSubtable ? {} : {color: 'var(--fgColor-muted)'}}
          data-testid="billing-requests-td"
        >
          <span>{cells[2]?.value}</span>
        </div>
        <div
          className={styles.fixedWidthCell}
          style={isSubtable ? {} : {color: 'var(--fgColor-muted)'}}
          data-testid="gross-amount-td"
        >
          <span>{cells[3]?.value}</span>
        </div>
        <div
          className={styles.fixedWidthCell}
          style={isSubtable ? {} : {fontWeight: 'bold'}}
          data-testid="billed-amount-td"
        >
          <span>{cells[4]?.value}</span>
        </div>
      </div>
    )
  }

  const useRichRowName = (groupBy?.type === UsageGrouping.ORG || groupBy?.type === UsageGrouping.USER) && cells[0]?.slug

  const getFirstColumnContent = (): React.ReactElement => {
    if (useRichRowName) {
      return (
        <Link href={`/${cells[0]?.slug}`} target="_blank" className={sharedStyles.columnAvatarStyle}>
          {cells[0]?.avatarSrc && (
            <GitHubAvatar square src={cells[0]?.avatarSrc} size={16} className="mr-2 flex-shrink-0" />
          )}
          {cells[0]?.name}
        </Link>
      )
    } else {
      return <span>{cells[0]?.value}</span>
    }
  }

  return (
    <div className={sharedStyles.borderTop}>
      {getRowContent()}
      <div className={sharedStyles.trStyle}>{open && <PremiumRequestUsageSubTable subtable={subtable} />}</div>
    </div>
  )
}

try{ PremiumRequestUsageTableRow.displayName ||= 'PremiumRequestUsageTableRow' } catch {}