import {Link, Button, Label} from '@primer/react'

import {formatMoneyDisplay} from '../../utils/money'
import {PAST_INVOICES_ROUTE, SHOW_INVOICE_ROUTE, PAY_INVOICE_ROUTE} from '../../routes'
import useRoute from '../../hooks/use-route'
import {useContext} from 'react'
import {PageContext} from '../../App'

import styles from '../usage/SummaryCardContainer.module.css'

export interface LatestInvoiceCardProps {
  latestInvoiceBalance: number
  invoiceDueDate: string
  invoiceNumber: string
  overdue: boolean
  meteredViaAzure: boolean
}

export default function LatestInvoiceCard(props: LatestInvoiceCardProps) {
  const {isStafftoolsRoute} = useContext(PageContext)

  const {path: pastInvoicesRoute} = useRoute(PAST_INVOICES_ROUTE)

  const {path: showInvoiceRoute} = useRoute(SHOW_INVOICE_ROUTE, {
    invoiceNumber: props.invoiceNumber,
  })

  const {path: payInvoiceRoute} = useRoute(PAY_INVOICE_ROUTE, {invoiceNumber: props.invoiceNumber})

  return (
    <div className={styles.card} data-testid="latest-invoice-card">
      <div className={styles.header}>
        <p className={styles.heading}>Latest invoice</p>

        <>
          {!isStafftoolsRoute && (
            <div>
              <Button as="a" href={payInvoiceRoute} variant="primary" size="small">
                Pay now
              </Button>
            </div>
          )}
        </>
      </div>

      <div className={styles.paymentContainer}>
        <div>
          <span className={styles.moneyDisplayText}>{formatMoneyDisplay(props.latestInvoiceBalance)}</span>
        </div>
        <div>
          {!props.overdue && <>by {props.invoiceDueDate}</>}
          {props.overdue && <Label variant="attention">Overdue</Label>}
        </div>
      </div>

      <div className={styles.paymentDueContainer}>
        {props.meteredViaAzure ? <p>Metered usage billed via Azure is not included.</p> : <br />}

        <p>
          {!isStafftoolsRoute && (
            <>
              <Link inline href={showInvoiceRoute} className={styles.link} target="_blank">
                View invoice
              </Link>
              {' | '}
            </>
          )}
          <Link inline href={pastInvoicesRoute} className={styles.link}>
            Past invoices
          </Link>
        </p>
      </div>
    </div>
  )
}

try{ LatestInvoiceCard.displayName ||= 'LatestInvoiceCard' } catch {}