import {useState} from 'react'
import useRequest from '../use-request'
import {COPILOT_USAGE_CHART_DATA_ROUTE} from '../../routes'

import {DEFAULT_PREMIUM_REQUESTS_GROUP_TYPE, ERRORS} from '../../constants'
import {RequestState, UsagePeriod} from '../../enums'

import type {Filters, UsageChartData} from '../../types/usage'
// eslint-disable-next-line no-restricted-imports
import {useToastContext} from '@github-ui/toast/ToastContext'

type UseCopilotUsageChartDataParams = {
  filters: Filters
}

function useCopilotUsageChartData({filters}: UseCopilotUsageChartDataParams) {
  const [usageChartData, setUsageChartData] = useState<UsageChartData[]>([])
  const [requestState, setRequestState] = useState<RequestState>(RequestState.INIT)
  const {addToast} = useToastContext()

  useRequest({
    route: COPILOT_USAGE_CHART_DATA_ROUTE,
    reqParams: {
      customer_id: filters.customer.id,
      group: (filters.group?.type ?? DEFAULT_PREMIUM_REQUESTS_GROUP_TYPE).toString(),
      period: (filters.period?.type ?? UsagePeriod.DEFAULT).toString(),
      query: filters.searchQuery,
    },
    onStart: () => {
      setUsageChartData([])
      setRequestState(RequestState.LOADING)
    },
    onSuccess: response => {
      setUsageChartData(response.data.usage)
      setRequestState(RequestState.IDLE)
    },
    onError: () => {
      setRequestState(RequestState.ERROR)
      // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
      addToast({
        type: 'error',
        message: ERRORS.QUERY_USAGE_ERROR,
      })
    },
  })

  return {usageChartData, requestState}
}

export default useCopilotUsageChartData
