import {useState} from 'react'
import useRequest from '../use-request'
import {COPILOT_USAGE_CARD_DATA_ROUTE} from '../../routes'

import {ERRORS} from '../../constants'
import {RequestState, UsagePeriod} from '../../enums'

import type {Filters, UsageCardData} from '../../types/usage'
// eslint-disable-next-line no-restricted-imports
import {useToastContext} from '@github-ui/toast/ToastContext'

type UseCopilotUsageCardDataParams = {
  filters: Filters
}

function useCopilotUsageCardData({filters}: UseCopilotUsageCardDataParams) {
  const [usageCardData, setUsageCardData] = useState<UsageCardData>({
    netBilledAmount: 0,
    netQuantity: 0,
    discountQuantity: 0,
  })
  const [requestState, setRequestState] = useState<RequestState>(RequestState.INIT)
  const {addToast} = useToastContext()

  useRequest({
    route: COPILOT_USAGE_CARD_DATA_ROUTE,
    reqParams: {
      customer_id: filters.customer.id,
      period: (filters.period?.type ?? UsagePeriod.DEFAULT).toString(),
      query: filters.searchQuery,
    },
    onStart: () => {
      setUsageCardData({
        netBilledAmount: 0,
        netQuantity: 0,
        discountQuantity: 0,
      })
      setRequestState(RequestState.LOADING)
    },
    onSuccess: response => {
      setUsageCardData({
        netBilledAmount: response.data.netBilledAmount,
        netQuantity: response.data.netQuantity,
        discountQuantity: response.data.discountQuantity,
        userPremiumRequestEntitlement: response.data.userPremiumRequestEntitlement,
      })
      setRequestState(RequestState.IDLE)
    },
    onError: () => {
      setRequestState(RequestState.ERROR)
      // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
      addToast({
        type: 'error',
        message: ERRORS.QUERY_USAGE_ERROR,
      })
    },
  })

  return {usageCardData, requestState}
}

export default useCopilotUsageCardData
